      'fonts.delete_confirm': '\u0423\u0434\u0430\u043B\u0438\u0442\u044C \u0441\u0435\u043C\u0435\u0439\u0441\u0442\u0432\u043E \u0448\u0440\u0438\u0444\u0442\u0430 \u00AB{name}\u00BB?',
