      'fonts.delete_error': '\u041E\u0448\u0438\u0431\u043A\u0430 \u0443\u0434\u0430\u043B\u0435\u043D\u0438\u044F: {msg}',
      'fonts.delete_btn': '\u0423\u0434\u0430\u043B\u0438\u0442\u044C',
      'fonts.convert_title': '\u041A\u043E\u043D\u0432\u0435\u0440\u0442\u0430\u0446\u0438\u044F \u0448\u0440\u0438\u0444\u0442\u0430 (TTF/OTF, \u0432 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0435)',
      'fonts.badge_beta': '\u0411\u0435\u0442\u0430',
      'fonts.convert_intro': '\u0420\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u0432 \u044D\u0442\u043E\u0439 \u0432\u043A\u043B\u0430\u0434\u043A\u0435 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430 \u2014 \u043D\u0430 \u0432\u0430\u0448\u0435\u043C \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u0435 \u0438\u043B\u0438 \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u0435, \u043D\u0435 \u043D\u0430 \u0440\u0438\u0434\u0435\u0440\u0435 \u2014 \u0437\u0430\u0442\u0435\u043C \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u0437\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u0442 \u0433\u043E\u0442\u043E\u0432\u044B\u0439 \u0444\u0430\u0439\u043B. \u0411\u0435\u0437 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F, \u0431\u0435\u0437 \u0441\u043A\u0440\u0438\u043F\u0442\u043E\u0432 \u043D\u0430 \u041F\u041A. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043F\u0430\u043F\u043A\u0443 \u0441 \u0444\u0430\u0439\u043B\u0430\u043C\u0438 \u043D\u0430\u0447\u0435\u0440\u0442\u0430\u043D\u0438\u0439 \u0448\u0440\u0438\u0444\u0442\u0430 (TTF/OTF) \u2014 Regular \u0438, \u043F\u043E \u0436\u0435\u043B\u0430\u043D\u0438\u044E, \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0438\u0435 \u0444\u0430\u0439\u043B\u044B Bold/Italic/Bold\u00A0Italic (\u043D\u0435 \u0438\u043C\u0438\u0442\u0430\u0446\u0438\u044F) \u2014 \u043E\u043D\u0438 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u0441\u043E\u043F\u043E\u0441\u0442\u0430\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u043F\u043E \u0438\u043C\u0435\u043D\u0438 \u0444\u0430\u0439\u043B\u0430 \u0438 \u0441\u043E\u0431\u0438\u0440\u0430\u044E\u0442\u0441\u044F \u0432 \u043E\u0434\u0438\u043D \u043C\u0443\u043B\u044C\u0442\u0438\u0441\u0442\u0438\u043B\u0435\u0432\u044B\u0439 .cpfont, \u0438\u0437 \u043A\u043E\u0442\u043E\u0440\u043E\u0433\u043E \u0440\u0438\u0434\u0435\u0440 \u0441\u0430\u043C \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442 \u043D\u0443\u0436\u043D\u044B\u0439 \u0441\u0442\u0438\u043B\u044C. \u041A\u0435\u0440\u043D\u0438\u043D\u0433\u0430/\u043B\u0438\u0433\u0430\u0442\u0443\u0440 \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u043D\u0435\u0442 (\u043D\u0443\u0436\u0435\u043D \u0440\u0430\u0437\u0431\u043E\u0440 \u0442\u0430\u0431\u043B\u0438\u0446 GPOS/GSUB, \u0432\u043D\u0435 \u0440\u0430\u043C\u043E\u043A \u044D\u0442\u043E\u0433\u043E \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u0430).',
