      'fonts.range_latin1': 'Latin-1 (\u0417\u0430\u043F\u0430\u0434\u043D\u0430\u044F \u0415\u0432\u0440\u043E\u043F\u0430)',
      'fonts.range_latin_ext': '\u0420\u0430\u0441\u0448\u0438\u0440\u0435\u043D\u043D\u0430\u044F \u043B\u0430\u0442\u0438\u043D\u0438\u0446\u0430',
