      'fonts.range_comprehensive': '\u041F\u043E\u043B\u043D\u044B\u0439 \u043D\u0430\u0431\u043E\u0440 (\u043B\u0430\u0442\u0438\u043D\u0438\u0446\u0430/\u043A\u0438\u0440\u0438\u043B\u043B\u0438\u0446\u0430/\u0433\u0440\u0435\u0447\u0435\u0441\u043A\u0438\u0439/\u0430\u0440\u043C\u044F\u043D\u0441\u043A\u0438\u0439/\u0438\u0432\u0440\u0438\u0442/\u0430\u0440\u0430\u0431\u0441\u043A\u0438\u0439/\u0434\u0435\u0432\u0430\u043D\u0430\u0433\u0430\u0440\u0438/\u0442\u0430\u0439\u0441\u043A\u0438\u0439/\u0433\u0440\u0443\u0437\u0438\u043D\u0441\u043A\u0438\u0439/CJK/\u0445\u0430\u043D\u0433\u044B\u043B\u044C/\u043A\u0430\u043D\u0430/\u0441\u0438\u043C\u0432\u043E\u043B\u044B)',
      'fonts.custom_ranges_label': '\u0421\u0432\u043E\u0438 \u0433\u043B\u0438\u0444\u044B, \u0434\u0438\u0430\u043F\u0430\u0437\u043E\u043D\u044B Unicode',
      'fonts.custom_ranges_note': '(\u043D\u0435\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E, \u0447\u0435\u0440\u0435\u0437 \u0437\u0430\u043F\u044F\u0442\u0443\u044E \u2014 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u043A \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u043C\u0443 \u0432\u044B\u0448\u0435 \u0434\u0438\u0430\u043F\u0430\u0437\u043E\u043D\u0443)',
      'fonts.convert_upload_btn': '\u041A\u043E\u043D\u0432\u0435\u0440\u0442\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0438 \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044C',
      'fonts.convert_hint': '\u00AB\u041F\u043E\u043B\u043D\u044B\u0439 \u043D\u0430\u0431\u043E\u0440\u00BB \u0437\u0430\u043F\u0440\u0430\u0448\u0438\u0432\u0430\u0435\u0442 \u0448\u0438\u0440\u043E\u043A\u0438\u0439 \u043D\u0430\u0431\u043E\u0440 \u043F\u0438\u0441\u044C\u043C\u0435\u043D\u043D\u043E\u0441\u0442\u0435\u0439 \u0438 \u0441\u0438\u043C\u0432\u043E\u043B\u044C\u043D\u044B\u0445 \u0431\u043B\u043E\u043A\u043E\u0432, \u043D\u043E \u0440\u0430\u0441\u0442\u0440\u0438\u0437\u0443\u044E\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u0442\u0435 \u0433\u043B\u0438\u0444\u044B, \u0447\u0442\u043E \u0440\u0435\u0430\u043B\u044C\u043D\u043E \u0435\u0441\u0442\u044C \u0432 \u0448\u0440\u0438\u0444\u0442\u0435 \u2014 \u043B\u0430\u0442\u0438\u043D\u0438\u0446\u0430/\u043A\u0438\u0440\u0438\u043B\u043B\u0438\u0446\u0430 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0431\u044B\u0441\u0442\u0440\u043E\u0439, \u0442\u0430\u043A \u043A\u0430\u043A \u0432\u0441\u0451 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u043E\u0435 \u043F\u0440\u043E\u043F\u0443\u0441\u043A\u0430\u0435\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u0431\u044B\u0441\u0442\u0440\u043E\u0439 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0438 \u043D\u0430\u043B\u0438\u0447\u0438\u044F. \u0428\u0440\u0438\u0444\u0442\u044B \u0441 \u0440\u0435\u0430\u043B\u044C\u043D\u044B\u043C \u043F\u043E\u043A\u0440\u044B\u0442\u0438\u0435\u043C CJK/\u0445\u0430\u043D\u0433\u044B\u043B\u044F \u043C\u043E\u0433\u0443\u0442 \u0437\u0430\u043D\u044F\u0442\u044C \u0432\u0440\u0435\u043C\u044F (\u0442\u044B\u0441\u044F\u0447\u0438 \u0433\u043B\u0438\u0444\u043E\u0432 \u043D\u0430 \u0441\u0442\u0438\u043B\u044C) \u2014 \u043E\u0441\u0442\u0430\u0432\u0430\u0439\u0442\u0435\u0441\u044C \u043D\u0430 \u044D\u0442\u043E\u0439 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0435 \u0434\u043E \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430. \u041D\u0443\u0436\u0435\u043D \u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E \u0441\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0439 \u0431\u0440\u0430\u0443\u0437\u0435\u0440 (\u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u044E\u0442\u0441\u044F FontFace \u0438 Canvas API). \u041F\u0440\u0430\u043A\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u0431\u0435\u0437 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u044F \u043F\u043E \u0440\u0430\u0437\u043C\u0435\u0440\u0443, \u0432 \u043E\u0442\u043B\u0438\u0447\u0438\u0435 \u043E\u0442 \u043A\u043E\u043D\u0432\u0435\u0440\u0442\u0430\u0446\u0438\u0438 \u043D\u0430 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0435 \u2014 \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0438\u0435 \u00AB\u0434\u0438\u0437\u0430\u0439\u043D\u0435\u0440\u0441\u043A\u0438\u0435\u00BB \u0448\u0440\u0438\u0444\u0442\u044B (Bookerly, Amazon Ember, Literata \u0438 \u043F\u043E\u0434\u043E\u0431\u043D\u044B\u0435) \u0440\u0430\u0431\u043E\u0442\u0430\u044E\u0442 \u043D\u043E\u0440\u043C\u0430\u043B\u044C\u043D\u043E. \u041A\u043E\u043D\u0432\u0435\u0440\u0442\u0438\u0440\u0443\u0435\u0442 \u0438 \u0437\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u0442 \u043E\u0434\u0438\u043D .cpfont \u043D\u0430 \u043A\u0430\u0436\u0434\u044B\u0439 \u0440\u0430\u0437\u043C\u0435\u0440 (12/14/16/18pt \u043F\u043B\u044E\u0441 \u0442\u043E, \u0447\u0442\u043E \u0432\u044B \u0434\u043E\u0431\u0430\u0432\u0438\u043B\u0438 \u0432\u044B\u0448\u0435) \u2014 \u043A\u0430\u0436\u0434\u0430\u044F \u0437\u0430\u0433\u0440\u0443\u0437\u043A\u0430 \u043F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0441 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u0438\u043C\u0438 \u0440\u0430\u0437\u043C\u0435\u0440\u0430\u043C\u0438 \u044D\u0442\u043E \u0437\u0430\u0439\u043C\u0451\u0442 \u0432\u0440\u0435\u043C\u044F. \u0421\u0432\u043E\u0439 \u0434\u0438\u0430\u043F\u0430\u0437\u043E\u043D\u044B \u2014 \u043E\u0434\u0438\u043D\u043E\u0447\u043D\u044B\u0439 \u043A\u043E\u0434\u043F\u043E\u0438\u043D\u0442 \u0438\u043B\u0438 \u0434\u0438\u0430\u043F\u0430\u0437\u043E\u043D \u0432\u0438\u0434\u0430 first-last, \u0441 \u043F\u0440\u0435\u0444\u0438\u043A\u0441\u043E\u043C 0x/U+ \u0438\u043B\u0438 \u0431\u0435\u0437 \u043D\u0435\u0433\u043E.',
      'fonts.upload_title': '\u0417\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044C \u0448\u0440\u0438\u0444\u0442',
